<script lang="ts">
 import {onMount} from 'svelte';
 import {fieldValue} from './field-values';
 import QuoteSidebar from './QuoteSidebar.svelte';
 import Icon from './WorkspaceIcon.svelte';
 import QuoteField from './QuoteField.svelte';
 import PaymentDetails from './PaymentDetails.svelte';
 import {pages,activePages,matches,quotesAPI,QuoteError,fieldDefaults,pageValues,type Quote,type Value,type FormPage,type SourceAction,type ImportedPolicy} from './quote-model';
 let list=$state<Quote[]>([]), quote=$state<Quote|null>(null), pageID=$state('newquote');
 let values=$state<Record<string,Value>>({}), rows=$state<Record<string,Value>[]>([]);
 let errors=$state<Record<string,string>>({}), error=$state(''), notice=$state(''), busy=$state(false), dirty=$state(false), creating=$state(false), loading=$state(true);
 let search=$state(''), tab=$state('pending'), pg=$state(0), recentIDs=$state<string[]>(readRecent());
 const PAGE=6;
 function readRecent():string[]{try{const v=JSON.parse(localStorage.getItem('recentQuotes')||'[]');return Array.isArray(v)?v:[];}catch{return [];}}
 function trackRecent(id:string){recentIDs=[id,...recentIDs.filter(x=>x!==id)].slice(0,20);try{localStorage.setItem('recentQuotes',JSON.stringify(recentIDs));}catch{/* storage unavailable */}}
 function pick(id:string){tab=id;pg=0;}
 let imports=$state<ImportedPolicy[]>([]), importError=$state(''), showSync=$state(false);
 const drafts=$derived(list.filter(q=>q.status!=='ready_for_rating'));
 const submitted=$derived(list.filter(q=>q.status==='ready_for_rating'));
 const recent=$derived(recentIDs.map(id=>list.find(q=>q.id===id)).filter((q):q is Quote=>!!q));
 const tabs=$derived([{id:'recent',label:'Recently Viewed',count:recent.length},{id:'pending',label:'Pending Quote',count:drafts.length},{id:'rating',label:'Awaiting Rating',count:submitted.length},{id:'migrated',label:'Migrated',count:imports.length}]);
 const needle=$derived(search.toLowerCase());
 const tabRows=$derived((tab==='recent'?recent:tab==='rating'?submitted:drafts).filter(q=>[q.number,q.source?.policy_number,q.values['AccountInput.FirstName'],q.values['AccountInput.LastName'],q.values['DwellingInput.Form']].join(' ').toLowerCase().includes(needle)));
 const importRows=$derived(imports.filter(p=>[p.policy_number,p.quote_number].join(' ').toLowerCase().includes(needle)));
 const pageCount=$derived(Math.max(1,Math.ceil((tab==='migrated'?importRows:tabRows).length/PAGE)));
 const cur=$derived(Math.min(pg,pageCount-1));
 const shown=$derived(tabRows.slice(cur*PAGE,cur*PAGE+PAGE));
 const shownImports=$derived(importRows.slice(cur*PAGE,cur*PAGE+PAGE));
 const oldest=(qs:Quote[])=>{const t=Math.min(...qs.map(q=>new Date(q.created_at??q.updated_at??Date.now()).getTime()));const d=Math.floor((Date.now()-t)/864e5);return d>0?'oldest waiting '+d+' day'+(d===1?'':'s'):'oldest from today';};
 const applicantName=(v:Record<string,Value>)=>[v['AccountInput.FirstName'],v['AccountInput.LastName']].filter(Boolean).join(' ')||'New applicant';
 let request=0; let mounted=false;
 const page=$derived(pages.find(p=>p.id===pageID)??pages[0]);
 const journey=$derived(activePages(values));
 const step=$derived(journey.findIndex(p=>p.id===pageID));
 const fields=$derived(page.fields.filter(f=>!f.hidden&&matches(f.showWhen,values)));
 const groups=$derived([...new Set(fields.map(f=>f.group??'Details'))]);
 const collection=$derived(page.collection&&matches(page.collection.when,values)?page.collection:undefined);
 const eligible=$derived(!!quote&&journey.filter(p=>p.id!=='review'&&p.id!=='payment').every(p=>quote!.completed.includes(p.id)));
 // Quotes saved before the payment step existed have no billing defaults yet.
 const paymentDefaults=fieldDefaults(pages.find(p=>p.id==='payment')?.fields??[]);
 function leaveOK(){return !dirty||window.confirm('You have unsaved changes. Discard them?');}
 function route(id?:string){history.replaceState(null,'',location.pathname+(id?`#personalhome/quote/${id}`:'#personalhome/newquote'));}
 function install(q:Quote,target=q.current_page){if(!mounted)return;quote=q;values={...paymentDefaults,...structuredClone($state.snapshot(q.values))};pageID=target;rows=structuredClone($state.snapshot(q.collections[pages.find(p=>p.id===target)?.collection?.key??'']??[]));errors={};error='';dirty=false;creating=false;route(q.id);window.scrollTo({top:0,behavior:'instant'});}
 function showError(e:unknown){error=e instanceof Error?e.message:String(e);errors=e instanceof QuoteError?e.fields:{};notice='';}
 async function load(){const token=++request;loading=true;error='';try{const id=location.hash.match(/^#personalhome\/quote\/([a-f0-9]{24})/)?.[1];if(id){const q=await quotesAPI.get(id);if(token===request)install(q);}else{const items=await quotesAPI.list();if(token===request){list=items;quote=null;creating=false;dirty=false;}quotesAPI.imports().then(p=>{if(token===request){imports=p;importError='';}}).catch(e=>{if(token===request){imports=[];importError=e instanceof Error?e.message:String(e);}});}}catch(e){if(token===request)showError(e);}finally{if(token===request)loading=false;}}
 onMount(()=>{mounted=true;void load();const before=(e:BeforeUnloadEvent)=>{if(dirty){e.preventDefault();e.returnValue='';}};const navigation=(e:Event)=>{if(!leaveOK()){e.preventDefault();route(quote?.id);}};const hash=()=>{if(!location.hash.startsWith('#personalhome'))return;if(!leaveOK()){route(quote?.id);return;}void load();};window.addEventListener('beforeunload',before);window.addEventListener('quote-before-leave',navigation);window.addEventListener('hashchange',hash);return()=>{mounted=false;request++;window.removeEventListener('beforeunload',before);window.removeEventListener('quote-before-leave',navigation);window.removeEventListener('hashchange',hash);};});
 function start(){if(!leaveOK())return;quote=null;creating=true;pageID='newquote';values=fieldDefaults(pages.flatMap(p=>p.fields));rows=[];errors={};error='';notice='';dirty=false;route();}
 async function open(q:Quote){if(!leaveOK())return;busy=true;error='';try{install(await quotesAPI.get(q.id));trackRecent(q.id);notice='';}catch(e){showError(e);}finally{busy=false;}}
 async function dashboard(){if(!leaveOK())return;dirty=false;route();await load();}
 function change(key:string,value:Value){if(key==='CoverageADwellingInput.Limit'&&typeof value==='number'&&values['DwellingInput.Form']==='HO3'){for(const [dependent,factor] of Object.entries({'CoverageCPersonalPropertyHO3Input.Limit':0.5,'CoverageDLossOfUseInput.Limit':0.2})){if(values[dependent]===null||values[dependent]===undefined||values[dependent]==='')values={...values,[dependent]:Math.round(value*factor)};}if(!values['ReplacementCostDwellingInput.ReplacementCostValue'])values={...values,'ReplacementCostDwellingInput.ReplacementCostValue':value};}values={...values,[key]:value};dirty=true;notice='';errors={...errors,[key]:''};if(key==='DwellingInput.Form'&&value==='HO6')values={...values,'DwellingInput.RoofGeometry':'NA','ReplacementCostDwellingInput.Indicator':false};}
 function updateRow(index:number,key:string,value:Value){rows=rows.map((row,i)=>i===index?{...row,[key]:value}:row);dirty=true;notice='';}
 function addRow(){if(!collection)return;rows=[...rows,fieldDefaults(collection.fields)];dirty=true;notice='';}
 function removeRow(index:number){rows=rows.filter((_,i)=>i!==index);dirty=true;notice='';errors={};}
 function navigate(target:FormPage){if(!quote||!leaveOK())return;install(quote,target.id);notice='';}
 function reachable(target:FormPage){if(!quote)return false;if(target.id==='payment')return quote.status==='ready_for_rating';if(quote.source)return true;const index=journey.findIndex(p=>p.id===target.id);return journey.slice(0,index).every(p=>quote!.completed.includes(p.id));}
 async function save(advance:boolean){if(busy)return;busy=true;error='';errors={};notice='';try{const saved=quote?await quotesAPI.save(quote,pageID,pageValues(page,values),rows,advance):await quotesAPI.create(pageValues(pages[0],values));install(saved);notice=page.id==='payment'?'Payment details saved.':advance?'Saved. Continue with the next step.':'Draft saved.';}catch(e){showError(e);}finally{busy=false;}}
 async function submit(){if(!quote||busy)return;busy=true;error='';try{const saved=await quotesAPI.submit(quote);install(saved);notice='Application submitted for rating. Add the payment details next.';}catch(e){showError(e);}finally{busy=false;}}
 function copyAddress(){for(const key of ['Address1','Address2','City','State','ZipCode','County'])values={...values,['LocationInput.'+key]:values['AccountInput.'+key]??''};dirty=true;notice='Applicant address copied. Save this page to keep it.';}
 function exportQuote(){if(!quote)return;const url=URL.createObjectURL(new Blob([JSON.stringify(quote,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=quote.number+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function sourceAction(action:SourceAction){
  if(action.kind==='copy-address')copyAddress();
  if(action.kind==='save-location')void save(false);
  if(action.kind==='cancel-location'&&quote&&leaveOK())install(quote,pageID);
  if(action.kind==='clear-location'){for(const key of ['Address1','Address2','City','State','ZipCode','County'])values={...values,['LocationInput.'+key]:''};dirty=true;notice='Draft location cleared. Save to keep this change, or Cancel to restore the saved location.';}
 }
 async function openPolicy(policy:ImportedPolicy){if(!leaveOK())return;busy=true;error='';try{install(await quotesAPI.importPolicy(policy.policy_number));notice=policy.quote_id?'':'Policy '+policy.policy_number+' opened from Helix. Fields the rater workbook does not have are empty.';}catch(e){showError(e);}finally{busy=false;}}
 async function syncNow(){if(!quote)return;try{const q=await quotesAPI.sync(quote);quote={...quote,helix:q.helix};}catch(e){showError(e);}}
 // While a sync is running, refresh only its state so the form keeps unsaved edits.
 $effect(()=>{const h=quote?.helix,id=quote?.id;if(!id||!h||(h.status!=='pending'&&h.status!=='syncing'))return;const timer=setTimeout(async()=>{try{const q=await quotesAPI.get(id);if(quote?.id===id)quote={...quote,helix:q.helix};}catch{}},1500);return()=>clearTimeout(timer);});
 const syncLabel:Record<string,string>={pending:'Helix: waiting to sync',syncing:'Helix: syncing…',synced:'Helix: synced',blocked:'Helix: not written',failed:'Helix: sync failed'};
 const when=(s:string)=>new Date(s).toLocaleString();
 const display=(v:Value|undefined)=>v===true?'Yes':v===false?'No':v===null||v===undefined||v===''?'Not provided':String(v);
</script>

<div class="application">
 <nav class="breadcrumb" aria-label="Breadcrumb"><button type="button" class="crumb" onclick={dashboard}>Workspace</button> <span>/</span> {#if quote||creating}<button type="button" class="crumb" onclick={dashboard}>Personal Home</button> <span>/</span> <span class="crumb-current" aria-current="page">{quote?.number??'New quote'}</span>{:else}<span class="crumb-current" aria-current="page">Personal Home</span>{/if}</nav>
 <div class="application-header"><div><span class="eyebrow">PERSONAL HOME · FLORIDA</span><h1>{quote?quote.number:creating?'Start a new quote':'Quote dashboard'}</h1><p class="muted">{quote?'Complete your application one step at a time.':'Create, save and resume PersonalHome applications.'}</p></div><div class="header-actions">{#if quote||creating}<button class="btn" disabled={busy} onclick={dashboard}>All quotes</button>{:else}<button class="btn primary" disabled={loading||busy} onclick={start}>Create quote</button>{/if}{#if quote}<span class="status">{quote.status==='ready_for_rating'?'Awaiting rating':'Draft'}</span>{#if quote.helix}<button class="sync-badge {quote.helix.status}" aria-expanded={showSync} onclick={()=>showSync=!showSync}>{syncLabel[quote.helix.status]??quote.helix.status}</button>{/if}{/if}</div></div>
 {#if quote&&showSync&&quote.helix}<section class="sync-panel" aria-label="Helix sync"><div><b>Helix policy {quote.helix.policy_number}</b> · quote version {quote.helix.quote_version} · {when(quote.helix.at)}{#if quote.helix.quote_version<quote.version} · <i>newer saves are queued</i>{/if}</div>{#if quote.helix.message}<p>{quote.helix.message}</p>{/if}{#if quote.helix.warnings?.length}<details><summary>{quote.helix.warnings.length} value{quote.helix.warnings.length===1?'':'s'} not written</summary><ul>{#each quote.helix.warnings as w}<li>{w}</li>{/each}</ul></details>{/if}{#if quote.helix.records?.length}<details><summary>{quote.helix.records.length} Helix records</summary><ul class="records">{#each quote.helix.records as r}<li><code>{r.variant}</code> {r.action}{#if r.record_id} <small>{r.record_id}</small>{/if}</li>{/each}</ul></details>{/if}<button class="btn sm" disabled={quote.helix.status==='pending'||quote.helix.status==='syncing'} onclick={syncNow}>Sync again</button></section>{/if}
 {#if error}<div class="message error" role="alert"><b>{error}</b>{#if Object.keys(errors).length}<ul>{#each Object.entries(errors).filter(([,v])=>v) as [key,message]}<li>{pages.flatMap(p=>p.fields).find(f=>f.key===key)?.label??key}: {message}</li>{/each}</ul>{/if}{#if !Object.keys(errors).length}<button class="btn sm" disabled={busy} onclick={()=>{if(leaveOK())void load();}}>Reload saved data</button>{/if}</div>{/if}
 {#if notice}<div class="message success" role="status">{notice}</div>{/if}
 {#if loading}<p role="status">Loading saved quotes…</p>
 {:else if !quote&&!creating}
  <div class="daily-split">
   <div class="daily-main">
    <div class="kpis">{#each [{id:'pending',label:'Pending Quotes',value:drafts.length,note:drafts.length?'to complete · '+oldest(drafts):'nothing waiting',icon:'clock',tone:'warning'},{id:'rating',label:'Awaiting Rating',value:submitted.length,note:'submitted, ready for rating',icon:'shield',tone:'success'},{id:'migrated',label:'Migrated Policies',value:imports.length,note:'from the rater workbook',icon:'file',tone:''}] as k}<button type="button" class="kpi" class:selected={tab===k.id} onclick={()=>pick(k.id)}><span class="kpi-icon {k.tone}"><Icon name={k.icon} size={14}/></span><span class="kpi-body"><span class="kpi-top"><span class="kpi-label">{k.label}</span><strong>{k.value}</strong></span><small>{k.note}</small></span></button>{/each}</div>
    <section class="widget">
     <div class="widget-header"><div><h2>Quotes</h2><p>Everything on your desk, sorted by status</p></div><label class="search"><Icon name="search" size={14}/><input type="search" aria-label="Search quotes" placeholder="Search quote, insured…" bind:value={search} oninput={()=>pg=0}/></label></div>
     <div class="widget-body">
      <div class="tabs" role="tablist" aria-label="Quote lists">{#each tabs as t}<button role="tab" aria-selected={tab===t.id} class:selected={tab===t.id} onclick={()=>pick(t.id)}>{t.label} <span>{t.count}</span></button>{/each}</div>
      <div class="table-wrap">
       {#if tab==='migrated'}
        <table><thead><tr><th>Policy No</th><th>Helix records</th><th>Migrated</th><th>Status</th><th class="act">Action</th></tr></thead><tbody>{#each shownImports as policy}<tr class="qrow" tabindex="0" onclick={()=>!busy&&openPolicy(policy)} onkeydown={(e)=>{if(e.key==='Enter'&&!busy)void openPolicy(policy);}}><td class="strong link">{policy.policy_number}</td><td>{policy.records}</td><td>{when(policy.written_at)}</td><td><span class="badge" class:primary={!!policy.quote_id}>{policy.quote_id?'Open as '+policy.quote_number:'Not opened'}</span></td><td class="act"><span class="go"><span class="kebab" aria-hidden="true">⋮</span></span></td></tr>{/each}</tbody></table>
        {#if importError}<p class="muted pad">Helix policies are unavailable: {importError}</p>{:else if !shownImports.length}<p class="muted pad">{imports.length?'No matching policies.':'No migrated policies yet. Upload a rater workbook in Migrate and run it.'}</p>{/if}
       {:else}
        <table><thead><tr><th>Quote No</th><th>Insured</th><th>Coverage Type</th><th>Effective Date</th><th>Status</th><th class="act">Action</th></tr></thead><tbody>{#each shown as item}<tr class="qrow" tabindex="0" onclick={()=>!busy&&open(item)} onkeydown={(e)=>{if(e.key==='Enter'&&!busy)void open(item);}}><td class="strong link">{item.number}</td><td>{applicantName(item.values)}{#if item.source}<small>Imported · {item.source.policy_number}</small>{/if}</td><td><span class="chip">{item.values['DwellingInput.Form']||'—'}</span></td><td>{item.values['PolicyInput.EffectiveDate']||'—'}</td><td><span class="badge" class:primary={item.status==='ready_for_rating'}>{item.status==='ready_for_rating'?'Awaiting rating':'Pending'}</span>{#if item.status==='ready_for_rating'&&item.completed.includes('payment')}<small>Payment captured</small>{/if}</td><td class="act"><button class="go" aria-label={'Open '+item.number} disabled={busy} onclick={(e)=>{e.stopPropagation();void open(item);}}><span class="kebab" aria-hidden="true">⋮</span></button></td></tr>{/each}</tbody></table>
        {#if !shown.length}<div class="empty"><Icon name="home" size={36}/><h3>{list.length?'Nothing here':'Your next home policy starts here'}</h3><p>{list.length?'Try another tab or search.':'Create an application to add applicant, property and coverage details.'}</p>{#if !list.length}<button class="btn primary" onclick={start}>Create your first quote</button>{/if}</div>{/if}
       {/if}
      </div>
      <nav class="pagination" aria-label="Pagination"><button aria-label="Previous page" disabled={cur===0} onclick={()=>pg=cur-1}>‹</button><span class="summary"><b>{cur+1}</b> / {pageCount}</span><button aria-label="Next page" disabled={cur>=pageCount-1} onclick={()=>pg=cur+1}>›</button></nav>
     </div>
    </section>
   </div>
   <aside class="rail">
    <div class="rail-title">Continue working</div>
    {#each drafts.slice(0,4) as item}<button type="button" class="action-card" disabled={busy} onclick={()=>open(item)}><span class="ac-top"><span class="ac-policy">{item.number}</span><span class="badge warn">Draft</span></span><span class="ac-row"><span class="chip">{item.values['DwellingInput.Form']||'—'}</span><span class="ac-date">{item.values['PolicyInput.EffectiveDate']||''}</span></span><span class="ac-facts"><span><small>Insured</small><b>{applicantName(item.values)}</b></span><span><small>Next step</small><b>{pages.find(p=>p.id===item.current_page)?.title}</b></span></span></button>{:else}<p class="muted pad">No draft applications. Start a new quote to begin.</p>{/each}
    <button class="btn primary" disabled={busy} onclick={start}><Icon name="plus" size={16}/>Create quote</button>
   </aside>
  </div>
 {:else}
  {#if quote?.source}<p class="info">Opened from Helix policy <b>{quote.source.policy_number}</b>, migrated from the rater workbook on {when(quote.source.imported_at)}. Every step can be viewed; fields the workbook does not have are empty, and saving writes your changes back to the same Helix policy.{#if quote.source.notes?.length} {quote.source.notes.length} value{quote.source.notes.length===1?' was':'s were'} not shown: {quote.source.notes.join(' ')}{/if}</p>{/if}
  <div class="quote-overview">
   <div class="overview-item"><span class="metric-icon"><Icon name="file"/></span><div><small>Quote number</small><strong>{quote?.number??'New application'}</strong></div></div>
   <div class="overview-item"><span class="metric-icon"><Icon name="home"/></span><div><small>Policy form</small><strong>{values['DwellingInput.Form']??'Select a form'}</strong></div></div>
   <div class="overview-item"><span class="metric-icon"><Icon name="user"/></span><div><small>Named insured</small><strong>{applicantName(values)}</strong></div></div>
   <div class="overview-item"><span class="metric-icon"><Icon name="calendar"/></span><div><small>Effective date</small><strong>{values['PolicyInput.EffectiveDate']||'Not selected'}</strong></div></div>
  </div>
   <nav class="quote-nav" aria-label="Quote steps">{#each journey as item,i}<button class:active={pageID===item.id} disabled={busy||!reachable(item)} aria-current={pageID===item.id?'step':undefined} onclick={()=>navigate(item)}><span>{quote?.completed.includes(item.id)||(item.id==='review'&&quote?.status==='ready_for_rating')?'✓':i+1}</span>{item.title}</button>{/each}</nav>
  <div class="quote-layout">
   <div class="quote-body">
    <section class="form-card"><div class="page-title"><div><span class="eyebrow">STEP {step+1} OF {journey.length}</span><h2>{page.title}</h2></div><span class="save-state">{dirty?'Unsaved changes':quote?'Saved on this computer':'New quote'}</span></div>
     {#if page.notice}<p class="info">{page.notice}</p>{/if}
     {#if pageID==='newquote'}<p class="muted">Start with your product and effective date. A quote number is assigned when you continue.</p>{/if}
     {#if pageID==='dwellinginfo'}<div class="copy-address"><p class="muted">Enter the insured property's address.</p><button class="btn sm" disabled={busy} onclick={copyAddress}>Copy applicant address</button></div>{/if}
     {#if pageID==='payment'}<PaymentDetails {fields} {values} {errors} {busy} {dirty} quoteId={quote?.id??''} submitted={quote?.status==='ready_for_rating'} policyNumber={quote?.source?.policy_number??quote?.number??''} onchange={change} onsave={()=>save(true)} onreset={()=>{if(quote){install(quote,pageID);notice='';}}} onprevious={()=>navigate(pages.find(p=>p.id==='review')!)} onnext={dashboard}/>{:else}
     <fieldset disabled={busy}>
      {#each groups as group (pageID+group)}<details class="field-group" open><summary><span class="section-icon"><Icon name={pageID==='dwellingcoverage'?'shield':'file'} size={15}/></span>{group}</summary><div class="field-grid">{#each fields.filter(f=>(f.group??'Details')===group) as field (pageID+field.key)}<QuoteField {field} id={'quote-'+field.key} value={values[field.key]} context={values} invalid={errors[field.key]} onchange={value=>change(field.key,value)}/>{/each}</div></details>{/each}
      {#if collection}<section class="repeat-section"><div class="repeat-heading"><h3>{collection.label}</h3><button data-source-ref={collection.sourceControls?.['collection-add']} type="button" class="btn sm" disabled={rows.length>=100} onclick={addRow}>+ Add {collection.key==='losses'?'loss':collection.key==='priorInsurance'?'prior policy':collection.key==='coapplicants'?'co-applicant':'interest'}</button></div>{#if errors[collection.key]}<p class="field-error">{errors[collection.key]}</p>{/if}{#if !rows.length}<p class="muted">No entries added.</p>{/if}
       {#each rows as row,i}<article class="repeat-row"><div class="repeat-heading"><b>{collection.key==='coapplicants'?'Co-applicant':collection.key==='losses'?'Loss':'Entry'} {i+1}</b><button data-source-ref={collection.sourceControls?.['collection-remove']} class="btn sm ghost" onclick={()=>removeRow(i)}>Remove entry {i+1}</button></div><details open class="row-details"><summary data-source-ref={collection.sourceControls?.['collection-details']}>Details</summary><div class="field-grid">{#each collection.fields.filter(f=>!f.hidden) as field}<QuoteField {field} id={collection.key+'-'+i+'-'+field.key} value={row[field.key]} context={{...values,...row}} rowIndex={i} invalid={errors[collection.key+'.'+i+'.'+field.key]} onchange={value=>updateRow(i,field.key,value)}/>{/each}</div></details></article>{/each}
      </section>{/if}
     </fieldset>
     {/if}
     {#if page.actions?.length}<section class="source-actions"><h3>Page actions</h3><div>{#each page.actions as action}<div class="source-action"><button data-source-ref={action.sourceRefs?.join(' ')} class="btn sm" disabled={busy||action.kind==='unavailable'} onclick={()=>sourceAction(action)}>{action.label}</button>{#if action.kind==='unavailable'}<small>{action.reason}</small>{/if}</div>{/each}</div></section>{/if}
     {#each page.servicePanels??[] as panel}<details class="service-panel"><summary>{panel.title}</summary><p class="muted">{panel.text}</p><dl>{#each panel.fields as label}<dt>{label}</dt><dd>{label==='Insured email address'?values['AccountInput.Email']||'Not provided':'Unavailable — service not connected'}</dd>{/each}</dl><div class="service-buttons">{#each panel.actions as label}<button class="btn sm" disabled>{label}</button>{/each}{#if panel.title==='Subscriber agreement and LPOA'}<button class="btn sm" disabled={busy} onclick={()=>navigate(pages.find(p=>p.id==='account')!)}>Return to Applicant</button>{/if}</div></details>{/each}
     {#if pageID==='summary'||pageID==='review'}
      <div class="rating"><span>Premium</span><strong>Awaiting rating</strong><p>No premium has been calculated. This application does not provide an insurance offer or coverage.</p></div>
      {#if pageID==='review'&&quote?.status==='ready_for_rating'}<div class="message success"><h3>Application captured</h3><p>{quote.number} has been saved and marked ready for rating. A carrier connection is required to obtain a premium and bind coverage.</p><button class="btn" onclick={exportQuote}>Download saved application</button></div>{/if}
      {#each journey.filter(p=>pageID==='review'?!['summary','review','payment'].includes(p.id):['newquote','dwellingcoverage'].includes(p.id)) as section}
       <details class="review-section" open={pageID==='summary'}><summary>{section.title} {#if quote?.completed.includes(section.id)}✓{/if}</summary><dl>{#each section.fields.filter(f=>!f.hidden&&matches(f.showWhen,values)) as f}<dt>{f.label}</dt><dd>{display(fieldValue(f,values)??f.unavailable)}</dd>{/each}</dl>{#if section.collection&&matches(section.collection.when,values)}{#each quote?.collections[section.collection.key]??[] as entry,i}<h4>{section.collection.label} {i+1}</h4><dl>{#each section.collection.fields as f}<dt>{f.label}</dt><dd>{display(fieldValue(f,{...values,...entry},i)??f.unavailable)}</dd>{/each}</dl>{/each}{/if}<button class="btn sm" disabled={busy} onclick={()=>navigate(section)}>Edit {section.title.toLowerCase()}</button></details>
      {/each}
     {/if}
     {#if pageID!=='payment'}<div class="form-actions">{#if quote&&step>0}<button class="btn" disabled={busy} onclick={()=>navigate(journey[step-1])}>← Back</button>{/if}<span class="spacer"></span>{#if pageID==='review'}<button class="btn primary" disabled={busy||!eligible||quote?.status==='ready_for_rating'} onclick={submit}>{busy?'Submitting…':quote?.status==='ready_for_rating'?'Submitted for rating':'Submit application for rating'}</button>{#if quote?.status==='ready_for_rating'}<button class="btn primary" disabled={busy} onclick={()=>navigate(pages.find(p=>p.id==='payment')!)}>Payment details →</button>{/if}{:else}{#if quote}<button class="btn" disabled={busy} onclick={()=>save(false)}>{busy?'Saving…':'Save draft'}</button>{/if}<button class="btn primary" disabled={busy} onclick={()=>save(true)}>{busy?'Saving…':creating?'Create quote & continue':'Save & continue →'}</button>{/if}</div>{/if}
    </section>
    <p class="footer-note">Your quote is stored on this computer and written to Helix each time you save. Rating, CLUE, payment processing and policy binding require carrier integrations.</p>
   </div>
   <QuoteSidebar {values} {quote} coapplicants={pageID==='account'?rows:quote?.collections.coapplicants??[]}/>
  </div>
 {/if}
</div>
